#include <stdio.h>
#include <assert.h>
#include <math.h>

#include "weightWindow.h"
#include "direction.h"


/* #define CHECK_WEIGHTS   */
/* enables printing weights as they are computed */

/* 
   Distribute flow to neighbors as in "The prediction of HIllslope
   Flow Paths for Distributed Hydrollogical Modeling using Digital
   Terrain Models" by Quinn, Chevallier, Planchon, in Hydrollogical
   Processes vol. 5, 1991

 */



/***************************************************************/
weightWindow::weightWindow(const float dx, const float dy) :
  cell_dx(dx), cell_dy(dy) {

  celldiag = sqrt(dx*dx + dy*dy);
  sumweight = sumcontour = 0;
}



/***************************************************************/
/* initialize all weights to 0 */
void
weightWindow::init() {
  sumweight = sumcontour = (float)0;
  for (int l = 0;l < 9; l++) {
    weight.set(l,(float)0);
  }
}

/***************************************************************/
/* set weight of neighbor (di,dj) equal to e_diff x
   computeContour/computeDist. This basically reduces to e_diff/2 (if
   not on diagonal) or e_diff/4 (if on diagonal). 
*/


void
weightWindow::computeWeight(const short di, const short dj, 
			    const elevation_type elev_crt,
			    const elevation_type elev_neighb) {

  /* NOTE: it is possible that elev_neighb is EDGE_NODATA. In this
     case, we just consider the value of EDGE_NODATA as an elevation,
     and push flow to it. Currently the value of EDGE_NODATA is -9998,
     and thus these cells will get most of the flow. */

  elevation_type e_diff = elev_crt - elev_neighb;
  assert(e_diff >= 0);
  if (di == 0 && dj == 0) {
    return;  
  }

  double contour, flow;

  if (dj==0) {
    flow = 0.5;
    contour = cell_dy/2;
  } else  if (di ==0) {
    flow = 0.5;
    contour = cell_dx/2;
  } else { /* on diagonal */
    flow = 0.25;
    contour = celldiag/4;
  }
  assert(contour > 0);

  /* at this point, 'flow' corresponds to the relative distance to the
   neighbor: 0.5 if horizontal/vertical, or 0.25 if diagonal. Diagonal
   points are further away. These are somewhat arbitrary; see paper.
   'contour' is the length perpendicular to the flow toward the
   neighbor. */

  if (e_diff > 0) {
    flow *= e_diff;
  } else {
    /* NOTE: how much flow to distribute to neighbors which are
       at same height?? */
    flow *=  1.0/contour; /* NOTE: this may cause overflow if contour
                             is v small */
  }
  weight.set(di, dj, flow);
  sumcontour += contour;
  sumweight += flow;
}



/***************************************************************/
/* computes and returns the distance corresponding to this direction */
double
weightWindow::computeDist(const short di, const short dj) {
  double dist;

  if (di == 0 && dj == 0) {
    return 0;
  }
  if (dj==0) {
    dist = cell_dy;
  } else  if (di ==0) {
    dist = cell_dx;
  } else { /* on diagonal */
    dist = celldiag;
  }
  assert(dist > 0);
  return dist;
}  

/***************************************************************/
/* computes and returns the contour corresponding to this direction */
double
weightWindow::computeContour(const short di, const short dj) {
  double contour;

  if (di == 0 && dj == 0) {
    return 0;
  }
  if (dj==0) {
    contour = cell_dy/2;
  } else  if (di ==0) {
    contour = cell_dx/2;
  } else { /* on diagonal */
    contour = celldiag/4;
  }
  assert(contour > 0);
  return contour;
}  

/***************************************************************/
/* compute the tanB corresponding to the elevation window and neighbor
   di,dj. */
double 
weightWindow::computeTanB(const short di,const short dj, 
			  const genericWindow<elevation_type>& elevwin) {

  assert(di != 0 || dj != 0);
  double dist = computeDist(di, dj);
  assert(dist > 0);
  return (elevwin.get() - elevwin.get(di, dj)) / dist;
}




/***************************************************************/
void
weightWindow::normalize() {
  if (sumweight > 0) {
    weight.scalarMultiply(1.0/sumweight);
  }
}


/***************************************************************/
/* compute the weights of the neighbors of a cell given an elevation
   window and precomputed directions dir; if trustdir = 1 then trust
   directions; otherwise push to all downslope neighbors and use dir
   only for cells which do not have any downslope neighbors */
/***************************************************************/
void 
weightWindow::compute(const dimension_type i, const dimension_type j,
		      const genericWindow<elevation_type>& elevwin, 
		      const direction_type dir,
		      const int trustdir) {

  elevation_type elev_crt, elev_neighb;

  /* initialize all weights to 0 */
  init();

  elev_crt = elevwin.get(); 
  assert(!is_nodata(elev_crt));

  /* map direction to neighbors */
  directionWindow dirwin(dir);  

  /* compute weights of the 8 neighbours  */
  int skipit = 0;
  for (short di = -1; di <= 1; di++) {
    for (short dj = -1; dj <= 1; dj++) {

      /* grid coordinates and elevation of neighbour */
      elev_neighb = elevwin.get(di, dj);

      skipit = ((di ==0) && (dj==0));
      skipit |= (elev_crt < elev_neighb);
      /* skipit |= (elev_neighb == edge_nodata); ?? */

      if (!trustdir) {
	dirwin.correctDirection(di,dj,skipit, i,j, elev_crt,dir,elev_neighb);
      }

      /* if direction points to it then compute its weight */
      if (dirwin.get(di,dj) == true) {
	computeWeight(di,dj, elev_crt, elev_neighb);
      }
    } /* for dj */
  } /* for di */
  normalize(); /* normalize the weights */

#ifdef CHECK_WEIGHTS 
  cout <<"weights: [";
  for (int l=0;l<9;l++) cout << form("%3.2f ",weight.get(l));
  cout <<"]\n";
#endif
};



/* Find the dominant direction. Set corresponding weight to 1, and
   sets all other weights to 0. Set sumweight and sumcontour.*/
void 
weightWindow::makeD8(const dimension_type i, const dimension_type j,
		     const genericWindow<elevation_type>& elevwin, 
		     const direction_type dir,
		     const bool trustdir) {


  elevation_type elev_crt;
  short di,dj;
  elev_crt = elevwin.get(); 
  assert(!is_nodata(elev_crt));

  int maxi=0, maxj=0;
  double tanb, contour, maxtanb = -1, maxcontour = -1;
  /* map direction to neighbors */
  directionWindow dirwin(dir); 

  /* compute biggest angle to a neighbor */
  for (di=-1; di <=1; di++) {
    for (dj = -1; dj <= 1; dj++) {
      if (dirwin.get(di,dj)) {

	tanb = computeTanB(di,dj, elevwin);
	contour = computeContour(di, dj);

	if (tanb > maxtanb) {
	  maxtanb = tanb;
	  maxi = di;
	  maxj = dj;
	  maxcontour = contour;
	}
      }
    }
  }
  /* at this point maxi and maxj must be set */
  assert((maxi != 0 || maxj != 0) && maxtanb >= 0);

  /* set weights corresponding to this direction */
  init();   /* initialize all weights to 0 */
  int maxindex = 3* (maxi + 1) + maxj+1;
  weight.set(maxindex,1);   /* set maxweight to 1 */

  sumweight = 1;
  sumcontour = maxcontour;
}

import { ToolsService } from './tools.service';
import { Graph, Link, Node } from './model/models';
import { of } from 'rxjs';

/**
 * Tests tools service.
 *
 * @author Janne Valkealahti
 */
describe('ToolsService', () => {

  const CONVERSION_RESPONSE_1 = {
    graph: null,
    dsl: 'timestamp',
    errors: []
  };

  const CONVERSION_RESPONSE_2 = {
    graph: {
      nodes: [
        {
          id: '0',
          name: 'START'
        },
        {
          id: '1',
          name: 'timestamp'
        },
        {
          id: '2',
          name: 'END'
        }
      ],
      links: [
        {
          from: '0',
          to: '1'
        },
        {
          from: '1',
          to: '2'
        }
      ]
    },
    dsl: null,
    errors: []
  };
  let mockHttp;
  let jsonData;
  let toolsService;

  beforeEach(() => {
    mockHttp = {
      post: jasmine.createSpy('post')
    };
    jsonData = {};
    toolsService = new ToolsService(mockHttp);
  });

  describe('parseTaskTextToGraph', () => {
    it('should call the tools service to parse dsl to graph', () => {
      mockHttp.post.and.returnValue(of(jsonData));
      toolsService.parseTaskTextToGraph('fakedsl');

      const httpUri1 = mockHttp.post.calls.mostRecent().args[0];
      const body = mockHttp.post.calls.mostRecent().args[1];
      const headerArgs1 = mockHttp.post.calls.mostRecent().args[2].headers;

      expect(httpUri1).toEqual('/tools/parseTaskTextToGraph');
      expect(body).toEqual(`{"dsl":"fakedsl","name":"unknown"}`);
      expect(headerArgs1.get('Content-Type')).toEqual('application/json');
      expect(headerArgs1.get('Accept')).toEqual('application/json');

    });
    it('empty DSL case', (done) => {
      toolsService.parseTaskTextToGraph('').toPromise().then(result => {
        expect(result.errors).toEqual([]);
        expect(result.dsl).toEqual('');
        expect(result.graph).toBeDefined();
        expect(result.graph.nodes).toEqual([]);
        expect(result.graph.links).toEqual([]);
        done();
      });
    });
    it('Multi-line DSL case', (done) => {
      const dsl = 'task ||\nanothertask';
      toolsService.parseTaskTextToGraph(dsl).toPromise().then(result => {
        expect(result.errors).toBeDefined();
        expect(result.errors.length).toBe(1);
        expect(result.errors[0].position).toBe(0);
        expect(result.errors[0].length).toBe(dsl.length);
        expect(result.dsl).toEqual(dsl);
        expect(result.graph).toBeNull();
        done();
      });
    });
  });

  describe('convertTaskGraphToText', () => {
    it('should call the tools service to parse graph to dsl', () => {
      mockHttp.post.and.returnValue(of(jsonData));
      const graph = new Graph(new Array(), new Array());
      toolsService.convertTaskGraphToText(graph);

      const httpUri1 = mockHttp.post.calls.mostRecent().args[0];
      const body = mockHttp.post.calls.mostRecent().args[1];
      const headerArgs1 = mockHttp.post.calls.mostRecent().args[2].headers;

      expect(httpUri1).toEqual('/tools/convertTaskGraphToText');
      expect(body).toEqual(`{"nodes":[],"links":[]}`);
      expect(headerArgs1.get('Content-Type')).toEqual('application/json');
      expect(headerArgs1.get('Accept')).toEqual('application/json');
    });
  });

  describe('extractConversionData', () => {
    it('should do correct conversion', () => {
      let taskConversion = toolsService.extractConversionData(CONVERSION_RESPONSE_1);
      expect(taskConversion.dsl).toBe('timestamp');
      taskConversion = toolsService.extractConversionData(CONVERSION_RESPONSE_2);
      expect(taskConversion.graph).toBeTruthy();
      expect(taskConversion.graph.nodes.length).toBe(3);
      expect(taskConversion.graph.links.length).toBe(2);
    });
  });

  describe('model', () => {
    it('graph to json', () => {
      const nodes: Array<Node> = new Array();
      nodes.push(new Node('id1', 'name1'));
      const links: Array<Link> = new Array();
      links.push(new Link('from1', 'to1'));
      const graph = new Graph(nodes, links);
      expect(graph.toJson())
        .toBe('{"nodes":[{"id":"id1","name":"name1"}],"links":[{"from":"from1","to":"to1"}]}');
    });
  });

});

Q:

Changing boolean from true to false and use it in if() afterward using jquery

I have tried several ways to implement the output from a boolean to an if-statement. Somehow I do it wrong. I'm able to change the value of the boolean and console.log it, so that should be right. I then try to use it in an if-statement, but somehow it is ignored and doesn't give the expected outcome. 
This is my code:
    var heroVelX = game.currentHero.GetLinearVelocity().x;
    var heroVelY = game.currentHero.GetLinearVelocity().y;
    var speed = Math.sqrt(Math.pow(heroVelX, 2) + Math.pow(heroVelY, 2));
    var moveOn = "";

    function delay(){   
        moveOn = Boolean(speed<1.5);
        console.log("Speed = " + speed + "  " + moveOn);    
    };  

    setTimeout(delay, 3500);

    // These are the conditions I have tried using. I can see in console.log that the value is changed. But somehow it is ignored? All the other conditions are accepted in the if-statement.       
    // moveOn ===!false
    // moveOn == true

    if(!game.currentHero.IsAwake() || moveOn === !false || heroX<0 || heroX >game.currentLevel.foregroundImage.width ){
            // then delete the old hero
            box2d.world.DestroyBody(game.currentHero);
            game.currentHero = undefined;
            // and load next hero
            game.mode = "load-next-hero";
        }

Can someone tell me what I'm doing wrong?

A:

You are doing several things wrong...
First of all, it's horrible to define a var as a String, and after that change it to boolean.
Secondly, put your boolean into a different log, and use dir instead.
The if statement its too confusing.
And there is no need to cast to Boolean.
Take a look at this:
var heroVelX = game.currentHero.GetLinearVelocity().x;
var heroVelY = game.currentHero.GetLinearVelocity().y;
